public class TracePatchDataAction : PatchDataAction {
	protected DebuggerDisassemblerPlugin plugin;

	public TracePatchDataAction(DebuggerDisassemblerPlugin plugin) : base(plugin)
    {
		this.plugin = plugin;
	}

	/* @Override */
	protected bool isApplicableToUnit(CodeUnit cu) {
		return base.isApplicableToUnit(cu) && cu is TraceData;
	}

	class PatchDataCommand : BackgroundCommand<TraceProgramView> {
		private byte[] encoded;

		public PatchDataCommand(byte[] encoded) {
			this.encoded = encoded;
		}

		/* @Override */
		public bool applyTo(TraceProgramView view, TaskMonitor monitor) {
			DebuggerControlService controlService = tool.getService(typeof(DebuggerControlService));
			if (controlService == null) {
				return true;
			}
			StateEditor editor = controlService.createStateEditor(view);
			Address address = getAddress();

			try {
				editor.setVariable(address, encoded).get(1, TimeUnit.SECONDS);
				doGoToNext(encoded.length);
				// Let the trace do everything regarding existing units
				return true;
			}
			catch (Exception e) when (e is InterruptedException or ExecutionException or TimeoutException) {
				setStatusMsg("Couldn't patch: " + e);
				Msg.error(this, "Couldn't patch", e);
				return false;
			}
		}
	}

	/* @Override */
	protected void applyPatch(AddressRange rng, byte[] encoded)
    {
		if (!(getProgram() is TraceProgramView view)) {
			return;
		}
		PatchDataCommand patch = new PatchDataCommand(encoded);
		patch.run(tool, view);
	}
}
